const marbleColors = ['#FF0000', '#0000FF', '#00FF00', '#FFFF00', '#FF00FF', '#00FFFF'];

for (let i = 0; i < 24; i++) {
    const x = (i % 8) * squareSize + squareSize / 2;
    const y = Math.floor(i / 8) * squareSize + squareSize / 2;

    // Randomly pick a color for the marble
    const colorIndex = Math.floor(Math.random() * marbleColors.length);
    const color = marbleColors[colorIndex];

    // Draw marble
    ctx.beginPath();
    ctx.arc(x, y, marbleRadius, 0, Math.PI * 2);
    ctx.fillStyle = color;
    ctx.fill();

    // Add some shading
    ctx.fillStyle = '#CCCCCC';
    ctx.globalAlpha = 0.3;
    ctx.beginPath();
    ctx.arc(x, y, marbleRadius - 3, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = 1.0;
}

