    ctx.lineTo(flower.x + 15, flower.y + 8);
    ctx.closePath();
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(flower.x + 12, flower.y);
    ctx.lineTo(flower.x + 25, flower.y - 8);
    ctx.lineTo(flower.x + 25, flower.y + 8);
    ctx.closePath();
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(flower.x + 10, flower.y);
    ctx.lineTo(flower.x + 15, flower.y - 8);
    ctx.lineTo(flower.x + 15, flower.y + 8);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = '#000';
}

