const maxRadius = Math.min(W, H) / 2 - 20;

const colors = [
  '#FFD700', // gold
  '#FFA500', // orange
  '#FF4500', // tomato
  '#8B0000', // dark red
  '#000080', // blue
  '#006400'  // forest green
];

for (let i = 0; i < 6; i++) {
  const radius = maxRadius - i * 20;
  ctx.beginPath();
  ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
  ctx.strokeStyle = colors[i];
  ctx.lineWidth = 2;
  ctx.stroke();
}

// Draw radial triangles
ctx.fillStyle = '#FFFFFF';
for (let angle = 0; angle < Math.PI * 2; angle += Math.PI / 8) {
  const x1 = centerX + Math.cos(angle) * (maxRadius - 10);
  const y1 = centerY + Math.sin(angle) * (maxRadius - 10);
  const x2 = centerX + Math.cos(angle + Math.PI / 4) * (maxRadius - 15);
  const y2 = centerY + Math.sin(angle + Math.PI / 4) * (maxRadius - 15);
  const x3 = centerX + Math.cos(angle - Math.PI / 4) * (maxRadius - 15);
  const y3 = centerY + Math.sin(angle - Math.PI / 4) * (maxRadius - 15);

  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.lineTo(x3, y3);
  ctx.closePath();
  ctx.fill();
}

