// Draw spiral with cool tones
function drawSpiral(x, y, r, depth) {
    if (depth > 0) {
        // Draw spiral arms
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + r * Math.cos(depth), y - r * Math.sin(depth));
        ctx.strokeStyle = `hsl(${360 - (depth * 10)}, 50%, ${50 + depth * 10}%)`;
        ctx.lineWidth = 2;
        ctx.lineCap = 'round';
        ctx.stroke();

        // Recursive calls for next arm
        drawSpiral(x + r * Math.cos(depth), y - r * Math.sin(depth), r * 0.8, depth - 1);
        drawSpiral(x + r * Math.cos(depth), y - r * Math.sin(depth), r * 0.8, depth - 1);
    }
}

